-- Node: st-exc-pta (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Peritonsillar Abscess","body":"Open [Peritonsillar Abscess (adult assessment and disposition)](#/tree/peritonsillar-abscess) or [Peritonsillar Abscess Drainage](#/tree/pta-drainage) for the drainage technique and management pathway.\n\n**Peritonsillar abscess (quinsy)** is the most common deep infection of the head and neck: unilateral severe sore throat, trismus, a “hot potato”/muffled voice, uvular deviation away from the affected side, and a bulging, fluctuant peritonsillar swelling. [8]\n\n**Next 5 minutes:**\n- Assess the airway (usually not critically threatened, but trismus + swelling can compromise it — escalate if red flags).\n- **Drainage** — needle aspiration or incision and drainage of the abscess (see the PTA consult); ENT if drainage is difficult, recurrent, or the diagnosis is uncertain.\n- **Antibiotics** covering Strep + oral anaerobes (e.g., amoxicillin-clavulanate, or clindamycin; ampicillin-sulbactam IV if unable to tolerate PO/severe).\n- **Analgesia + IV fluids** (odynophagia limits intake); a single dose of IV/oral corticosteroid (dexamethasone) reduces pain and improves recovery.\n- Point-of-care ultrasound (intraoral) can differentiate abscess from cellulitis and guide drainage; CT if deep extension suspected.\n\n🛑 Cellulitis (no drainable pus) is treated with antibiotics + steroids, not drainage — ultrasound helps avoid a dry, painful stab. 🛑 Trismus severe enough to prevent drainage, or bilateral/atypical findings, warrants ENT and imaging.","citation":[8],"recommendation":"Drain the abscess (needle aspiration or I&D; ENT if difficult), antibiotics (Strep + anaerobe cover), analgesia, IV fluids, and a dose of dexamethasone. Ultrasound distinguishes abscess from cellulitis. Escalate airway if red flags.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'st-exc-pta' AND tree_id = 'sore-throat-hub';

-- Node: trach-vs-laryngectomy (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Tracheostomy or Laryngectomy?","body":"**Laryngectomy = Total surgical removal of larynx**\n- NO connection between oropharynx and airway\n- CANNOT be intubated from above\n- Stoma is the ONLY airway\n\n**Tracheostomy = Tube through trachea, larynx intact**\n- Upper airway may be patent\n- Can potentially oxygenate/intubate from above\n- Dual oxygenation strategy possible\n\n**If uncertain:** Attempt to feel airflow from mouth during ventilation. No airflow = likely laryngectomy. [1][2]","citation":[1,2],"options":[{"label":"Tracheostomy (upper airway intact)","next":"trach-assessment"},{"label":"Laryngectomy (stoma only airway)","next":"laryngectomy-emergency","urgency":"critical"},{"label":"Unknown - proceed with caution","next":"trach-assessment","urgency":"urgent"}],"images":[{"src":"images/trach-emergency/airway-routes-atlas.jpg","alt":"Sagittal comparison of a tracheostomy and a total laryngectomy with an end stoma.","caption":"A tracheostomy may retain upper airway continuity. After total laryngectomy the stoma is the only airway. Original myMedKitt atlas illustration."}],"summary":"Laryngectomy = NO oral airway possible; tracheostomy = dual airway — check bedside sign"}'::jsonb
WHERE id = 'trach-vs-laryngectomy' AND tree_id = 'trach-emergency';

