UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"Bleeding: Timing & Severity","body":"[Open Tracheo-Innominate Fistula and RAPID](#/tree/tracheo-innominate-fistula) for suspected arterial hemorrhage.\n\n**Tracheostomy bleeding - assess timing and severity:**\n\n**Early bleeding (<48 hours post-op):**\n- Usually minor: skin edges, granulation\n- Related to suctioning, manipulation\n- Rarely life-threatening\n\n**Late bleeding (>72 hours, especially 7-14 days):**\n- **HIGH RISK for tracheo-innominate fistula (TIF)**\n- Innominate artery erosion - mortality approaches 50%\n- Any late bleeding may be \"sentinel bleed\" before massive hemorrhage\n\n**Sentinel bleed:**\n- Small self-limited bleed preceding massive hemorrhage (up to 50% of TIF cases)\n- **TREAT ANY LATE BLEEDING AS POTENTIAL TIF** [4][6][7][8]","citation":[4,6,7,8],"options":[{"label":"Minor oozing, stable patient","next":"trach-bleeding-minor"},{"label":"Moderate bleeding, 7-21 days post-trach","next":"trach-bleeding-tif-concern","urgency":"critical"},{"label":"Massive hemorrhage","next":"trach-bleeding-massive","urgency":"critical"}],"calculatorLinks":[{"id":"trach-bleeding","label":"Bleeding Risk Assessment"}],"summary":"Late bleeding >72h = sentinel bleed for tracheo-innominate fistula until proven otherwise","safetyLevel":"critical"}'::jsonb
WHERE id = 'trach-bleeding-start' AND tree_id = 'trach-emergency';

-- Node: tif-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Tracheo-Innominate Fistula","body":"[TIF Steps Summary](#/info/tif-steps)\n\n**Tracheo-Innominate Fistula (TIF)** is a catastrophic complication of tracheostomy with near-100% mortality without intervention and 50-70% mortality even with surgery. [1][2]\n\n**Key Principle:** Massive hemorrhage occurring 3 days to 6 weeks after tracheostomy is **TIF until proven otherwise**. [1][3]\n\n**Incidence:** 0.1-1% of tracheostomies; accounts for ~10% of significant tracheostomy bleeds. [2]\n\n**This consult covers:**\n- Recognizing the sentinel bleed (warning sign)\n- Cuff hyperinflation technique\n- Finger tamponade (Utley maneuver)\n- Surgical activation\n- Stabilization and airway management\n\n**Time is critical.** A sentinel bleed precedes massive hemorrhage by only 24-48 hours. [1][4]","citation":[1,2,3,4],"next":"tif-timing-check","images":[{"src":"images/tracheo-innominate-fistula/fistula-atlas.jpg","alt":"Paired cutaways of intact arterial and tracheal walls and a fistula carrying blood into the airway.","caption":"A defect between the innominate artery and anterior tracheal wall allows arterial blood to enter the airway. Schematic, not to scale. Original myMedKitt atlas illustration."}],"summary":"TIF is near-100% fatal without surgery; sentinel bleed precedes massive hemorrhage by 24-48 hours","skippable":true}'::jsonb
WHERE id = 'tif-start' AND tree_id = 'tracheo-innominate-fistula';

